// --------------------------AHInfoParser类成员函数定义-------------------------------------
ge::graphStatus AHInfoParser::GetOpName()
{
    if (context_->GetNodeName() == nullptr) {
        OP_LOGE("AiInfraAggregateHidden", "opName got from TilingContext is nullptr");
        return ge::GRAPH_FAILED;
    }
    opName_ = context_->GetNodeName();
    return ge::GRAPH_SUCCESS;
}

ge::graphStatus AHInfoParser::GetNpuInfo()
{
    platformInfo_ = context_->GetPlatformInfo();
    OP_CHECK_IF(platformInfo_ == nullptr, OP_LOGE(opName_, "GetPlatformInfo is nullptr."), return ge::GRAPH_FAILED);

    auto ascendcPlatform = platform_ascendc::PlatformAscendC(platformInfo_);
    aivNum_ = static_cast<int64_t>(ascendcPlatform.GetCoreNumAiv());
    uint32_t aicNum = ascendcPlatform.GetCoreNumAic();
    OP_CHECK_IF(aicNum == 0 || aivNum_ == 0, OP_LOGE(opName_, "num of core obtained is 0."), return GRAPH_FAILED);
    socVersion_ = ascendcPlatform.GetSocVersion();
    if ((socVersion_ != platform_ascendc::SocVersion::ASCEND910B) &&
        (socVersion_ != platform_ascendc::SocVersion::ASCEND910_93)) {
        OP_LOGE(opName_, "SOC Version[%d] is not support.", (int32_t)socVersion_);
        return GRAPH_FAILED;
    }
    OP_CHECK_IF(context_->GetWorkspaceSizes(1) == nullptr,
        OP_LOGE(opName_, "workSpaceSize got from ge is nullptr"),
        return ge::GRAPH_FAILED);
    OP_CHECK_IF(context_->GetRawTilingData() == nullptr,
        OP_LOGE(context_->GetNodeName(), "RawTilingData got from GE context is nullptr."),
        return ge::GRAPH_FAILED);

    return ge::GRAPH_SUCCESS;
}

ge::graphStatus AHInfoParser::CheckInputValid()
{
    // 1.获取变量相关参数
    opParamInfo_.input.desc = context_->GetInputDesc(INPUT_INDEX);
    opParamInfo_.input.shape = context_->GetInputShape(INPUT_INDEX);
    // 2.检查变量是否存在
    OP_CHECK_IF(opParamInfo_.input.shape == nullptr,
        OP_LOGE(opName_, "Shape of tensor input is nullptr"),
        return ge::GRAPH_FAILED);
    OP_CHECK_IF(opParamInfo_.input.desc == nullptr,
        OP_LOGE(opName_, "Desc of tensor input is nullptr"),
        return ge::GRAPH_FAILED);
    // 3.检查变量类型
    inputType_ = opParamInfo_.input.desc->GetDataType();
    OP_CHECK_IF(((inputType_ != ge::DT_FLOAT16) && (inputType_ != ge::DT_BF16)),
        OP_LOGE(opName_, "The data types of the input must be float16 or bfloat16."),
        return ge::GRAPH_FAILED);
    // 4.检查变量Shape的Dim
    int64_t inputShapeDim = opParamInfo_.input.shape->GetStorageShape().GetDimNum();
    int64_t inputExpectShapeDim = DIM_NUM_THREE;
    OP_CHECK_IF(inputShapeDim != inputExpectShapeDim,
        OP_LOGE(
            opName_, "the dim num of input's shape should be %u, but now is %u", inputExpectShapeDim, inputShapeDim),
        return ge::GRAPH_FAILED);
    // 5.检查变量shape大小是否超限 input [S,B,H],
    //  -----------------------check S Size-------------------
    sSize_ = static_cast<int64_t>(opParamInfo_.input.shape->GetStorageShape().GetDim(DIM_IDX_ZERO));

