15	using torch::autograd::AutogradContext;
16	using torch::autograd::Function;
17	using variable_list = std::vector<at::Tensor>;
18	
19	namespace custom {
20	using namespace at_npu::native;
21	
22	// 为NPU设备实现前向接口
23	at::Tensor npu_aggregate_hidden_npu(
24	    const at::Tensor &input, const at::Tensor &weight, const c10::optional<at::Tensor> &mask)
25	{
26	    // 1. 准备输出张量
27	    std::vector<c10::SymInt> output_size{input.size(0), input.size(1), input.size(2)};
28	    at::Tensor output = at::empty_symint(output_size, input.options());
29	
30	    // 2. 调用NPU算子
31	    EXEC_NPU_CMD_V1(aclnnAiInfraAggregateHidden, input, weight, mask, output);  // mask为空直接传
32	
33	    return std::move(output);
34	}
35	
36	// 为NPU设备实现反向接口
37	::std::tuple<at::Tensor, at::Tensor> npu_aggregate_hidden_grad_npu(const at::Tensor &grad_output,
38	    const at::Tensor &input, const at::Tensor &weight, const c10::optional<at::Tensor> &mask)
39	{
40	    // 准备输出张量
41	    std::vector<c10::SymInt> grad_input_size{input.size(0), input.size(1), input.size(2)};
42	    std::vector<c10::SymInt> grad_weight_size{weight.size(0), weight.size(1)};
43	    auto grad_input = at::empty_symint(grad_input_size, input.options());
44	    auto grad_weight = at::empty_symint(grad_weight_size, input.options());
45	
46	    // 调用NPU反向算子
47	    EXEC_NPU_CMD_V1(aclnnAiInfraAggregateHiddenGrad, grad_output, input, weight, mask, grad_input, grad_weight);
48	
49	    return std::make_tuple(std::move(grad_input), std::move(grad_weight));
50	}
51	
52	// Autograd Function类
53	class AiInfraAggregateHiddenFunction : public torch::autograd::Function<AiInfraAggregateHiddenFunction> {
54	public:
55	    static variable_list forward(
56	        AutogradContext *ctx, const at::Tensor &input, const at::Tensor &weight, const c10::optional<at::Tensor> &mask)
57	    {
58	        at::AutoDispatchBelowADInplaceOrView guard;  // 避免递归调用AD
59	
60	        // 1. 查找并调用注册的NPU前向算子
61	        static auto op = torch::Dispatcher::singleton()
62	                             .findSchemaOrThrow("custom::npu_aggregate_hidden", "")
63	                             .typed<decltype(npu_aggregate_hidden_npu)>();
64	
65	        at::Tensor output = op.call(input, weight, mask);
66	
67	        // 2. 保存前向输出
68	        ctx->save_for_backward({output.detach(), input, weight, mask.value_or(at::Tensor())});
69	
70	        // 3. 返回前向输出
71	        return {output};
72	    }
73	
74	    static variable_list backward(AutogradContext *ctx, variable_list grad_outputs)
75	    {
76	        // 1. 恢复前向保存的变量
77	        auto saved = ctx->get_saved_variables();
78	        at::Tensor output = saved[0];  // 前向输出
79	        at::Tensor input = saved[1];
80	        at::Tensor weight = saved[2];
81	
82	        // 恢复mask（如果存在）
83	        c10::optional<at::Tensor> mask = saved[3].defined() ? c10::optional<at::Tensor>(saved[3]) : c10::nullopt;
84	
85	        // 2. 梯度处理
86	        at::Tensor grad = grad_outputs[0];
87	        if (grad_outputs.size() > 0 && grad.defined()) {
88	            grad = grad.contiguous();  // 确保梯度内存连续（NPU算子要求）
89	        } else {
90	            grad = at::zeros_like(output);  // 梯度未定义时补0
91	        }
92	
93	        // 3. 查找并调用注册的NPU反向算子
94	        static auto op = torch::Dispatcher::singleton()
95	                             .findSchemaOrThrow("custom::npu_aggregate_hidden_grad", "")
96	                             .typed<decltype(npu_aggregate_hidden_grad_npu)>();
97	
98	        auto grads = op.call(grad, input, weight, mask);
